    survey = collections.Counter()
    for it in orders.values():
        survey["status=" + repr(it.get("status"))] += 1
        if not is_int(it.get("amount_cents")):
            survey["non-int amount: " + repr(it.get("amount_cents"))] += 1
        elif it["amount_cents"] < 0:
            survey["negative amount"] += 1
        t, kind = parse_ts(it.get("placed_at"))
        survey["ts kind=" + (kind if t is not None else "UNPARSED")] += 1
        if set(it) != {"id", "customer_id", "status", "placed_at", "amount_cents"}:
            survey["unexpected keys " + repr(sorted(it))] += 1

    q, problems = qualifying(orders)
    if problems:
        raise FatalError(f"unparseable timestamps on shipped orders: {problems[:10]}")

    customers = {}
    cdir = os.path.join(run_dir, "customers")
    for name in os.listdir(cdir):
        with open(os.path.join(cdir, name), "rb") as f:
            d = json.loads(f.read())
        customers[d["id"]] = d

    by_region = {r: 0 for r in REGIONS}
    total = 0
    issues = []
    for it in q:
        cust = customers.get(it["customer_id"])
        if cust is None:
            issues.append(("no customer record", it))
            continue
        pct, region = cust["discount_pct"], cust["region"]
        if not is_int(pct) or not 0 <= pct <= 100:
            issues.append((f"bad discount_pct {pct!r}", it))
            continue
        if region not in by_region:
            issues.append((f"unknown region {region!r}", it))
            continue
        if not is_int(it["amount_cents"]) or it["amount_cents"] < 0:
            issues.append((f"bad amount {it['amount_cents']!r}", it))
            continue
        v = discounted(it["amount_cents"], pct)
        by_region[region] += v
        total += v

    if issues:
        for msg, it in issues[:20]:
            print("ISSUE:", msg, it)
        raise FatalError(f"{len(issues)} qualifying orders could not be valued; not writing result")

    assert sum(by_region.values()) == total
    result = {
        "total_cents": total,
        "order_count": len(q),
        "duplicates_skipped": dup,
        "by_region": by_region,
    }
    print("pages:", len(pages), "listings:", sum(len(p["items"]) for p in pages.values()),
          "distinct:", len(orders), "duplicates:", dup, "conflicting duplicates:", len(conflicts))
    for oid, a, b in conflicts[:20]:
        print("CONFLICT", oid, a, b)
    print("survey:")
    for k, v in sorted(survey.items()):
        print(f"  {k}: {v}")
    print(json.dumps(result, indent=2))
    with open(out_path, "w") as f:
        json.dump(result, f, indent=2)
        f.write("\n")


if __name__ == "__main__":
    cmd = sys.argv[1]
    if cmd == "fetch":
        cmd_fetch(sys.argv[2])
    elif cmd == "compute":
        cmd_compute(sys.argv[2], sys.argv[3])
    else:
        sys.exit(__doc__)

